"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["15967"],{3402(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.estrutura_formulario.item_fora_de_secao","status":422,"titulo":"O item precisa estar numa se\xe7\xe3o do formul\xe1rio"},"descricao":{"codigo":"uniplus.estrutura_formulario.item_fora_de_secao","requisitos":[],"oQueAconteceu":["Um item, ou um grupo, aponta em `paginaCodigo` para uma p\xe1gina que n\xe3o existe no formul\xe1rio ou que \xe9 um bloco de sistema, e s\xf3 a se\xe7\xe3o recebe itens. Nos modelos de formul\xe1rio a regra \xe9 mais estrita: o item sem `paginaCodigo` tamb\xe9m \xe9 recusado, porque todo item do modelo precisa estar numa se\xe7\xe3o. Na grava\xe7\xe3o dos itens do processo, o item ainda sem se\xe7\xe3o \xe9 aceito, e s\xf3 o `paginaCodigo` declarado \xe9 conferido. A mensagem \xe9 \\"O item \'`{c\xf3digo\\\\}`\' precisa estar numa se\xe7\xe3o do formul\xe1rio.\\", com o c\xf3digo do fato do item ou do grupo.","Na grava\xe7\xe3o dos itens e nos modelos, a recusa vem na lista `errors`, com `field` igual a `itens[i].paginaCodigo` (nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`), em que `i` conta primeiro os itens e depois os grupos, na ordem em que vieram. Na grava\xe7\xe3o do formul\xe1rio do processo, a recusa vem quando as p\xe1ginas novas deixariam sem se\xe7\xe3o os itens j\xe1 gravados, e o `field` \xe9 `paginas`, com a mensagem nomeando o item. Nada \xe9 gravado.","Nos modelos de formul\xe1rio, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Aponte `paginaCodigo` para o `codigo` de uma p\xe1gina do tipo se\xe7\xe3o do formul\xe1rio e, nos modelos, informe-o em todo item. Na grava\xe7\xe3o do formul\xe1rio do processo, mantenha entre as p\xe1ginas a se\xe7\xe3o a que os itens j\xe1 gravados pertencem, ou mova antes os itens para outra se\xe7\xe3o."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio","Grava\xe7\xe3o do formul\xe1rio do processo"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Estrutura formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);